// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract SentinelNotary {
    address public owner;
    string public currentRoot;

    event Notarized(string merkleRoot, uint256 timestamp);

    constructor() {
        owner = msg.sender;
    }

    function setRoot(string memory _newRoot) public {
        require(msg.sender == owner, "Only 2A Agency can anchor new proofs");
        currentRoot = _newRoot;
        emit Notarized(_newRoot, block.timestamp);
    }
}
